function i(e){if(e==null||e==="")return"—";const n=typeof e=="string"?Number(e):e;return Number.isFinite(n)?`¥${(n/100).toLocaleString("zh-CN",{maximumFractionDigits:3})}`:"—"}function u(e){return e==null?"—":e.toLocaleString("zh-CN")}function a(e){return`${(e*100).toFixed(2)}%`}function o(e){return e==null?"—":e<1e3?`${e} ms`:`${(e/1e3).toFixed(2)} s`}function c(e){if(!e)return"—";const n=new Date(e);return Number.isNaN(n.getTime())?e:n.toLocaleString("zh-CN",{timeZone:"Asia/Shanghai",hour12:!1,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"})}const t={queued:"排队中",running:"运行中",succeeded:"成功",failed:"失败",cancelled:"已取消"};function f(e){return t[e]??e}function d(e){switch(e){case"succeeded":return"success";case"running":return"warning";case"failed":return"danger";default:return"info"}}export{a,i as b,o as c,c as d,f as e,u as f,d as s};
